CREATE TABLE "TarifaProfesional" ("id" TEXT NOT NULL PRIMARY KEY,"tenantId" TEXT NOT NULL,"sucursalId" TEXT NOT NULL,"barberoId" TEXT NOT NULL,"servicioId" TEXT NOT NULL,"version" INTEGER NOT NULL,"precio" DECIMAL(65,30),"vigenteDesde" TIMESTAMP(3) NOT NULL,"vigenteHasta" TIMESTAMP(3),"anulada" BOOLEAN NOT NULL DEFAULT false,"usuarioId" TEXT NOT NULL,"fecha" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "TarifaProfesional_scope_version_key" ON "TarifaProfesional"("tenantId","sucursalId","barberoId","servicioId","version");
CREATE INDEX "TarifaProfesional_tenantId_sucursalId_vigenteDesde_idx" ON "TarifaProfesional"("tenantId","sucursalId","vigenteDesde");
CREATE TABLE "PoliticaDescuento" ("id" TEXT NOT NULL PRIMARY KEY,"tenantId" TEXT NOT NULL,"sucursalId" TEXT NOT NULL,"version" INTEGER NOT NULL,"activa" BOOLEAN NOT NULL DEFAULT true,"limitesJson" TEXT NOT NULL,"motivoObligatorio" BOOLEAN NOT NULL,"vigenciaAprobacionMinutos" INTEGER NOT NULL,"usuarioId" TEXT NOT NULL,"fecha" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "PoliticaDescuento_tenantId_sucursalId_version_key" ON "PoliticaDescuento"("tenantId","sucursalId","version");
CREATE TABLE "AprobacionDescuento" ("id" TEXT NOT NULL PRIMARY KEY,"tenantId" TEXT NOT NULL,"sucursalId" TEXT NOT NULL,"solicitadoPorId" TEXT NOT NULL,"rolSolicitante" TEXT NOT NULL,"cartHash" TEXT NOT NULL,"carritoJson" TEXT NOT NULL,"resumenJson" TEXT NOT NULL,"motivo" TEXT NOT NULL,"politicaVersion" INTEGER,"estado" TEXT NOT NULL DEFAULT 'PENDIENTE',"aprobadoPorId" TEXT,"aprobadoPorNombre" TEXT,"aprobadoEn" TIMESTAMP(3),"expiraEn" TIMESTAMP(3),"ventaId" TEXT,"fecha" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "AprobacionDescuento_ventaId_key" ON "AprobacionDescuento"("ventaId");
CREATE INDEX "AprobacionDescuento_tenantId_sucursalId_estado_fecha_idx" ON "AprobacionDescuento"("tenantId","sucursalId","estado","fecha");
